// frontend/src/pages/Dashboard.jsx
import React from 'react';
import { useAuth } from '../context/AuthContext';

const Dashboard = () => {
  const { user } = useAuth();

  const renderContent = () => {
    switch (user.role) {
      case 'admin':
        return (
          <div>
            <h3 className="text-xl font-semibold">Quản trị hệ thống</h3>
            <p>Quản lý người dùng, cấu hình AI, xem báo cáo tổng hợp.</p>
          </div>
        );
      case 'manager':
        return (
          <div>
            <h3 className="text-xl font-semibold">Quản lý thu mua</h3>
            <p>Phê duyệt giao dịch lớn, xem báo cáo lợi nhuận, hiệu suất AI.</p>
          </div>
        );
      case 'purchasing_staff':
        return (
          <div>
            <h3 className="text-xl font-semibold">Nhân viên thu mua</h3>
            <p>Nhập thông tin xe, xem giá đề xuất từ AI, thương lượng với khách.</p>
            {/* Ở đây có thể thêm form định giá */}
          </div>
        );
      case 'technician':
        return (
          <div>
            <h3 className="text-xl font-semibold">Kỹ thuật viên</h3>
            <p>Kiểm tra tình trạng kỹ thuật xe, cập nhật đánh giá.</p>
          </div>
        );
      default:
        return (
          <div>
            <h3 className="text-xl font-semibold">Khách hàng</h3>
            <p>Xem thông tin xe đã bán, theo dõi giao dịch.</p>
          </div>
        );
    }
  };

  return (
    <div className="container mx-auto p-8">
      <h2 className="text-2xl font-bold mb-4">Dashboard</h2>
      <div className="bg-white p-6 shadow rounded">
        <p><strong>Xin chào, {user.name}</strong> (Vai trò: {user.role})</p>
        <hr className="my-4" />
        {renderContent()}
      </div>
    </div>
  );
};

export default Dashboard;
